#include <stdio.h>
#include <string.h>

typedef struct {
    char name[16];
    long long bytes;
    int alive;
} Block;

Block blocks[1000];
int block_count = 0;

Block *find_alive(const char *name) {
    for (int i = 0; i < block_count; i++) {
        if (blocks[i].alive && strcmp(blocks[i].name, name) == 0) return &blocks[i];
    }
    return NULL;
}

int main(void) {
    int n;
    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        char cmd[16], name[16];
        long long bytes = 0;
        scanf("%15s %15s", cmd, name);
        if (strcmp(cmd, "free") != 0) scanf("%lld", &bytes);

        if (strcmp(cmd, "alloc") == 0) {
            Block *b = &blocks[block_count++];
            strcpy(b->name, name);
            b->bytes = bytes;
            b->alive = 1;
            continue;
        }
        Block *b = find_alive(name);
        if (b == NULL) {
            printf("bad %s %s\n", cmd, name);
        } else if (strcmp(cmd, "free") == 0) {
            b->alive = 0;
        } else {
            b->bytes = bytes;
        }
    }

    long long total = 0;
    int leaked = 0;
    for (int i = 0; i < block_count; i++) {
        if (blocks[i].alive) {
            total += blocks[i].bytes;
            leaked++;
        }
    }
    if (leaked == 0) {
        printf("no leaks\n");
        return 0;
    }
    printf("leaked %lld bytes in %d blocks\n", total, leaked);
    for (int i = 0; i < block_count; i++) {
        if (blocks[i].alive) printf("%s %lld\n", blocks[i].name, blocks[i].bytes);
    }
    return 0;
}
